    {
      "i": 3,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "आपको कितने idol या piece चाहिए?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "हमको एक single piece चाहिए घर के लिए दो inch से कितने का मिल जाएगा madam ये?"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "बहुत बढ़िया घर के लिए चाहिए समझ गई।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "price seller ही बताएंगे मैं उन्हें connect कराऊंगी।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "अब शिवलिंग height में 2 inch चाहिए।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "सही है ना?"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "हाँ हाँ।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "अब बताइए किस material में चाहिए natural stone या metal या कुछ और पसंद करेंगे?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "Madam सस्ते में चाहिए हम लोग बहुत गरीब आदमी खाली शौक है की यहाँ नर्मदा जी से machine घर में आ जाए तो अब marble में छोटा कितना से दो inch तक कितना पड़ जाएगा?"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "समझ गई आप marble में छोटा और सस्ते में चाहते हैं।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "price की पूरी जानकारी seller ही देंगे।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "पहले आपके city और state बता दीजिए please।"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 20,
      "speaker": "caller",
      "text": "हमारा UP Fatehpur district है।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "आप Fatehpur Uttar Pradesh से बोल रहे हैं ना?"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "आप W जी बोल रहे हैं ना?"
    },
    {
      "i": 25,
      "speaker": "caller",
      "text": "जी।"
    }
  ]
